use rhwp::{wasm_api::HwpDocument,model::style::FontTypeOrigin};
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
fn request(kind:&str)->Value{if kind=="footnote"{json!({"kind":kind,"section":0,"parent":0,"control":2})}else{json!({"kind":kind,"section":0,"applyTo":2})}}
fn own(kind:&str)->(HwpDocument,Value){let mut d=HwpDocument::create_empty();d.create_blank_document().unwrap();d.insert_text(0,0,0,"본문").unwrap();let r;if kind=="footnote"{let v:Value=serde_json::from_str(&d.insert_footnote(0,0,1).unwrap()).unwrap();d.insert_text_in_footnote(0,v["paraIdx"].as_u64().unwrap() as u32,v["controlIdx"].as_u64().unwrap() as u32,0,2,"각😀주").unwrap();r=json!({"kind":kind,"section":0,"parent":v["paraIdx"],"control":v["controlIdx"]});}else{d.create_header_footer(0,kind=="header",2).unwrap();d.insert_text_in_header_footer(0,kind=="header",2,0,0,"머😀리말").unwrap();r=request(kind);} (d,r)}
fn observed(d:&HwpDocument,r:&Value)->Value{let v:Value=serde_json::from_str(&d.get_session_story_evidence(&r.to_string())).unwrap();assert_eq!(v["complete"],true,"complete story evidence required: {v}");v}
// Exactly the existing JS session-story semantic contract: only its typed root
// paragraph provenance and already-declared no-fill sentinels are excluded.
// No font field, unknown property or raw shape ID is removed by this harness.
fn meaning(v:&Value)->Value{match v{Value::Array(a)=>Value::Array(a.iter().map(meaning).collect()),Value::Object(o)=>{let no_fill=o.get("fillType").and_then(Value::as_str)==Some("none");Value::Object(o.iter().filter(|(k,_)|!no_fill||!["fillColor","patternColor","patternType"].contains(&k.as_str())).map(|(k,v)|(k.clone(),meaning(v))).collect())},_=>v.clone()}}
fn semantic(d:&HwpDocument,r:&Value)->Value{let mut v=observed(d,r);let p=v.as_object_mut().unwrap().remove("provenance").unwrap();assert_eq!(p["kind"],"generated-paragraph-record-identities");meaning(&v)}
fn roundtrip(kind:&str){let(d,r)=own(kind);let before=semantic(&d,&r);for bytes in [d.export_hwp().unwrap(),d.export_hwpx().unwrap()]{let after=HwpDocument::new(&bytes).unwrap();assert_eq!(semantic(&after,&r),before,"{kind} save/reopen story mismatch");}assert_eq!(semantic(&d,&r),before,"export mutated live story");}
fn set_types(d:&mut HwpDocument,code:u8,origin:Option<FontTypeOrigin>){let mut model=d.document().clone();for group in &mut model.doc_info.font_faces{for font in group{font.alt_type=code;font.hwpx_type_origin=origin.clone();font.raw_data=None;}}d.set_document(model);}
#[test]fn real_header_both_formats_restore_same_semantic_story(){roundtrip("header")}
#[test]fn real_footer_both_formats_restore_same_semantic_story(){roundtrip("footer")}
#[test]fn real_footnote_both_formats_restore_same_semantic_story(){roundtrip("footnote")}
#[test]fn consistent_hft_spelling_only_is_native_equivalent(){let(mut d,r)=own("header");set_types(&mut d,2,None);let before=semantic(&d,&r);set_types(&mut d,2,Some(FontTypeOrigin::HwpFont));assert_eq!(semantic(&d,&r),before);}
#[test]fn representative_zero_is_not_merged_with_unknown_native_zero(){let(mut d,r)=own("header");set_types(&mut d,0,None);let before=semantic(&d,&r);set_types(&mut d,0,Some(FontTypeOrigin::Representative));assert_ne!(semantic(&d,&r),before);}
#[test]fn opaque_unknown_type_spelling_remains_in_story_identity(){let(mut d,r)=own("header");set_types(&mut d,0,Some(FontTypeOrigin::Unrecognized("OWN-UNKNOWN-A".into())));let before=semantic(&d,&r);set_types(&mut d,0,Some(FontTypeOrigin::Unrecognized("OWN-UNKNOWN-B".into())));assert_ne!(semantic(&d,&r),before);}
#[test]fn missing_required_type_is_not_merged_with_native_none(){let(mut d,r)=own("header");set_types(&mut d,0,None);let before=semantic(&d,&r);set_types(&mut d,0,Some(FontTypeOrigin::Missing));assert_ne!(semantic(&d,&r),before);}
#[test]fn inconsistent_known_type_claim_remains_observable(){let(mut d,r)=own("header");set_types(&mut d,2,None);let before=semantic(&d,&r);set_types(&mut d,2,Some(FontTypeOrigin::TrueType));assert_ne!(semantic(&d,&r),before);}
#[test]fn real_font_name_change_is_not_hidden_by_canonical_source_type(){let(mut d,r)=own("header");set_types(&mut d,1,Some(FontTypeOrigin::TrueType));let before=semantic(&d,&r);let mut model=d.document().clone();for group in &mut model.doc_info.font_faces{for font in group{font.name.push_str("-OWN-CHANGED");}}d.set_document(model);assert_ne!(semantic(&d,&r),before);}
#[test]fn original_v1_full_font_and_paragraph_wire_are_exactly_compatible(){let(d,r)=own("header");let p=std::path::PathBuf::from(std::env::var("JUEONY_REPO").unwrap()).join("build/session-font-provenance-closure84/legacy-v1-wire83.json");let legacy:Value=serde_json::from_slice(&std::fs::read(p).unwrap()).unwrap();let current=observed(&d,&r);assert_eq!(current["context"][0]["host"]["characters"][0]["properties"]["fonts"],legacy["fontResources"]);assert_eq!(current["context"][0]["paragraphProperties"],legacy["paragraphResource"]);}
#[test]fn every_present_xml_direction_stays_observable(){use rhwp::model::style::ParagraphTextDirection;let(mut d,r)=own("header");let base=d.document().clone();let before=semantic(&d,&r);for direction in [ParagraphTextDirection::Auto,ParagraphTextDirection::Ltr,ParagraphTextDirection::Rtl,ParagraphTextDirection::Unknown("OWN-OPAQUE-DIRECTION".into())]{let mut model=base.clone();for shape in &mut model.doc_info.para_shapes{shape.hwpx_text_direction=Some(direction.clone());}d.set_document(model);let current=semantic(&d,&r);assert_ne!(current,before);assert!(current["context"][0]["paragraphProperties"].as_object().unwrap().contains_key("hwpx_text_direction"));}}
#[test]fn compiled_runtime_file_is_exact_strict_applied_candidate(){let bytes=include_bytes!("../src/wasm_api/session_story.rs");let p=std::path::PathBuf::from(std::env::var("JUEONY_REPO").unwrap()).join("build/session-font-provenance-closure84/source-candidate/src/wasm_api/session_story.rs");assert_eq!(Sha256::digest(bytes).as_slice(),Sha256::digest(std::fs::read(p).unwrap()).as_slice());}
